def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple[str, str, str, int]] = []
    rejected: list[int] = []

    def parse_amount(token: str) -> int:
        if token and token.isascii() and token.isdigit():
            return int(token)
        return -1

    for i, op in enumerate(ops):
        parts = op.split(" ")
        if any(part == "" for part in parts):
            rejected.append(i)
            continue

        verb = parts[0]
        n_parts = len(parts)

        if verb == "open" and n_parts == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if amount >= 0 and acc not in balances:
                balances[acc] = amount
                history.append(("open", acc, "", amount))
            else:
                rejected.append(i)
        elif verb == "deposit" and n_parts == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if amount > 0 and acc in balances:
                balances[acc] += amount
                history.append(("deposit", acc, "", amount))
            else:
                rejected.append(i)
        elif verb == "withdraw" and n_parts == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if (
                amount > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amount
            ):
                balances[acc] -= amount
                history.append(("withdraw", acc, "", amount))
            else:
                rejected.append(i)
        elif verb == "transfer" and n_parts == 4:
            src, dst = parts[1], parts[2]
            amount = parse_amount(parts[3])
            if (
                amount > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amount
            ):
                balances[src] -= amount
                balances[dst] += amount
                history.append(("transfer", src, dst, amount))
            else:
                rejected.append(i)
        elif verb == "freeze" and n_parts == 2:
            acc = parts[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc, "", 0))
            else:
                rejected.append(i)
        elif verb == "unfreeze" and n_parts == 2:
            acc = parts[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc, "", 0))
            else:
                rejected.append(i)
        elif verb == "undo" and n_parts == 1:
            if not history:
                rejected.append(i)
            else:
                h_verb, acc1, acc2, amount = history.pop()
                if h_verb == "open":
                    del balances[acc1]
                elif h_verb == "deposit":
                    balances[acc1] -= amount
                elif h_verb == "withdraw":
                    balances[acc1] += amount
                elif h_verb == "transfer":
                    balances[acc1] += amount
                    balances[acc2] -= amount
                elif h_verb == "freeze":
                    frozen.remove(acc1)
                elif h_verb == "unfreeze":
                    frozen.add(acc1)
        else:
            rejected.append(i)

    return balances, rejected
